#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int L, C;
    cin >> L >> C;

    bool black[6][6] = {};
    int P;
    cin >> P;

    while (P--) {
        int x, y;
        cin >> x >> y;
        black[x - 1][y - 1] = true;
    }

    bool eligible[6][6] = {};
    int total = 0;
    const int dr[] = {-1, 1, 0, 0};
    const int dc[] = {0, 0, -1, 1};

    for (int r = 0; r < L; ++r) {
        for (int c = 0; c < C; ++c) {
            if (black[r][c]) continue;

            for (int d = 0; d < 4; ++d) {
                int nr = r + dr[d], nc = c + dc[d];
                if (nr >= 0 && nr < L && nc >= 0 && nc < C && black[nr][nc]) {
                    eligible[r][c] = true;
                    ++total;
                    break;
                }
            }
        }
    }

    int match[6][6];
    memset(match, -1, sizeof(match));

    function<bool(int, int, bool[6][6])> augment = [&](int r, int c, bool seen[6][6]) {
        for (int d = 0; d < 4; ++d) {
            int nr = r + dr[d], nc = c + dc[d];
            if (nr < 0 || nr >= L || nc < 0 || nc >= C ||
                !eligible[nr][nc] || seen[nr][nc]) continue;

            seen[nr][nc] = true;
            if (match[nr][nc] == -1 || augment(match[nr][nc] / C, match[nr][nc] % C, seen)) {
                match[nr][nc] = r * C + c;
                return true;
            }
        }
        return false;
    };

    int matching = 0;
    for (int r = 0; r < L; ++r) {
        for (int c = 0; c < C; ++c) {
            if (!eligible[r][c] || (r + c) % 2 != 0) continue;
            bool seen[6][6] = {};
            if (augment(r, c, seen)) ++matching;
        }
    }

    cout << total - matching << '\n';
    return 0;
}
